export const getListActivityUrl = (params?: ListActivityParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/activity?${stringifiedParams}` : `/api/activity`
}

/**
 * @summary List recent school changes
 */
export const listActivity = async (params?: ListActivityParams, options?: Parameters<typeof customFetch>[1]): Promise<ActivityRecord[]> => {

  return customFetch<ActivityRecord[]>(getListActivityUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





